mapper.select:
SELECT pl.entry_time, pl.exit_time, m.car_number AS carNumber, IFNULL(pmt.total_fee, 0) AS fee FROM parking_log pl JOIN member m ON pl.member_id = m.member_id LEFT JOIN payment pmt ON pl.payment_id = pmt.payment_id WHERE m.member_id = #{memberId}
AND DATE(pl.entry_time) BETWEEN #{startDate} AND #{endDate}
ORDER BY pl.entry_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM parking_log pl
JOIN member m ON pl.member_id = m.member_id
WHERE m.member_id = #{memberId}

    AND DATE(pl.entry_time) BETWEEN #{startDate} AND #{endDate}
